// @FunctionalInterface: ONE abstract + default composition + static factories
package com.bank.brokerage.function;

import com.bank.brokerage.model.Trade;
import java.math.BigDecimal;
import java.math.RoundingMode;

@FunctionalInterface
public interface FeeCalculator {

    // ═══ THE ONE ABSTRACT METHOD ═══
    BigDecimal calculate(Trade trade);

    // ═══ DEFAULT METHODS: composition (like Predicate.and, Function.andThen) ═══

    default FeeCalculator withMinimum(BigDecimal min) {
        return trade -> {
            BigDecimal fee = this.calculate(trade);
            return fee.compareTo(min) < 0 ? min : fee;
        };
    }

    default FeeCalculator withMaximum(BigDecimal max) {
        return trade -> {
            BigDecimal fee = this.calculate(trade);
            return fee.compareTo(max) > 0 ? max : fee;
        };
    }

    default FeeCalculator withDiscount(BigDecimal discountRate) {
        return trade -> {
            BigDecimal fee = this.calculate(trade);
            BigDecimal discount = fee.multiply(discountRate);
            return fee.subtract(discount).setScale(2, RoundingMode.HALF_UP);
        };
    }

    // ═══ STATIC FACTORIES: common strategies ═══

    static FeeCalculator flatFee(BigDecimal amount) {
        return trade -> amount;
    }

    static FeeCalculator percentageFee(BigDecimal rate) {
        return trade -> trade.getAmount().multiply(rate).setScale(2, RoundingMode.HALF_UP);
    }

    static FeeCalculator tieredFee(BigDecimal lowerRate, BigDecimal upperRate, BigDecimal threshold) {
        return trade -> {
            BigDecimal amount = trade.getAmount();
            if (amount.compareTo(threshold) <= 0) {
                return amount.multiply(lowerRate).setScale(2, RoundingMode.HALF_UP);
            }
            BigDecimal lowerPart = threshold.multiply(lowerRate);
            BigDecimal upperPart = amount.subtract(threshold).multiply(upperRate);
            return lowerPart.add(upperPart).setScale(2, RoundingMode.HALF_UP);
        };
    }
}
