// ─── File: src/main/java/com/bank/brokerage/service/BrokerageService.java ───
package com.bank.brokerage.service;

import com.bank.brokerage.dto.FeeResult;
import com.bank.brokerage.function.FeeCalculator;
import com.bank.brokerage.model.Trade;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class BrokerageService {

    private final EntityManager em;

    @Value("${brokerage.default-rate:0.001}")
    private BigDecimal defaultRate;

    @Value("${brokerage.minimum-fee:20}")
    private BigDecimal minimumFee;

    @Value("${brokerage.maximum-fee:2500}")
    private BigDecimal maximumFee;

    @Transactional(readOnly = true)
    public List<FeeResult> calculateAllStrategies(String tradeId) {
        Trade trade = em.find(Trade.class, tradeId);
        if (trade == null) throw new IllegalArgumentException("Not found: " + tradeId);

        // Strategy 1: flat fee (lambda)
        FeeCalculator flat = FeeCalculator.flatFee(new BigDecimal("20"));

        // Strategy 2: percentage fee (static factory → lambda)
        FeeCalculator percentage = FeeCalculator.percentageFee(defaultRate);

        // Strategy 3: percentage + minimum + maximum (COMPOSED with defaults!)
        FeeCalculator composed = FeeCalculator.percentageFee(defaultRate)
            .withMinimum(minimumFee)     // default method composition
            .withMaximum(maximumFee);    // default method composition

        // Strategy 4: tiered (0.1% up to 5L, 0.05% above) + 10% discount
        FeeCalculator tiered = FeeCalculator.tieredFee(
                new BigDecimal("0.001"), new BigDecimal("0.0005"), new BigDecimal("500000"))
            .withDiscount(new BigDecimal("0.10"));  // 10% discount

        return List.of(
            new FeeResult(tradeId, trade.getSymbol(), trade.getAmount(),
                flat.calculate(trade), "Flat Rs.20"),
            new FeeResult(tradeId, trade.getSymbol(), trade.getAmount(),
                percentage.calculate(trade), "0.1% of amount"),
            new FeeResult(tradeId, trade.getSymbol(), trade.getAmount(),
                composed.calculate(trade), "0.1% with min Rs.20 + max Rs.2500"),
            new FeeResult(tradeId, trade.getSymbol(), trade.getAmount(),
                tiered.calculate(trade), "Tiered (0.1%/0.05%) with 10% discount")
        );
    }
}
