package com.bank.brokerage.function;

import com.bank.brokerage.model.Trade;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class FeeCalculatorTest {

    @Test
    void shouldCalculateFlatFee() {
        Trade trade = mock(Trade.class);
        FeeCalculator flat = FeeCalculator.flatFee(new BigDecimal("20"));
        assertThat(flat.calculate(trade)).isEqualByComparingTo("20");
    }

    @Test
    void shouldCalculatePercentageFee() {
        Trade trade = mock(Trade.class);
        when(trade.getAmount()).thenReturn(new BigDecimal("245050"));
        FeeCalculator pct = FeeCalculator.percentageFee(new BigDecimal("0.001"));
        assertThat(pct.calculate(trade)).isEqualByComparingTo("245.05");
    }

    @Test
    void shouldApplyMinimum() {
        Trade smallTrade = mock(Trade.class);
        when(smallTrade.getAmount()).thenReturn(new BigDecimal("4208")); // 0.1% = Rs.4.21
        FeeCalculator withMin = FeeCalculator.percentageFee(new BigDecimal("0.001"))
            .withMinimum(new BigDecimal("20"));
        assertThat(withMin.calculate(smallTrade)).isEqualByComparingTo("20"); // minimum applies
    }

    @Test
    void shouldApplyMaximum() {
        Trade largeTrade = mock(Trade.class);
        when(largeTrade.getAmount()).thenReturn(new BigDecimal("3520000")); // 0.1% = Rs.3520
        FeeCalculator withMax = FeeCalculator.percentageFee(new BigDecimal("0.001"))
            .withMaximum(new BigDecimal("2500"));
        assertThat(withMax.calculate(largeTrade)).isEqualByComparingTo("2500"); // maximum caps it
    }

    @Test
    void shouldComposeMinAndMax() {
        Trade trade = mock(Trade.class);
        when(trade.getAmount()).thenReturn(new BigDecimal("245050")); // 0.1% = Rs.245.05
        FeeCalculator composed = FeeCalculator.percentageFee(new BigDecimal("0.001"))
            .withMinimum(new BigDecimal("20"))
            .withMaximum(new BigDecimal("2500"));
        assertThat(composed.calculate(trade)).isEqualByComparingTo("245.05"); // within range
    }

    @Test
    void shouldApplyDiscount() {
        Trade trade = mock(Trade.class);
        when(trade.getAmount()).thenReturn(new BigDecimal("245050")); // 0.1% = Rs.245.05
        FeeCalculator discounted = FeeCalculator.percentageFee(new BigDecimal("0.001"))
            .withDiscount(new BigDecimal("0.10")); // 10% off
        assertThat(discounted.calculate(trade)).isEqualByComparingTo("220.55"); // 245.05 - 10%
    }

    @Test
    void annotationIsOptionalButLambdaStillWorks() {
        // Even without @FunctionalInterface, lambdas work on any 1-abstract-method interface
        interface UnannotatedFI { String transform(String input); }
        UnannotatedFI upper = String::toUpperCase;
        assertThat(upper.transform("reliance")).isEqualTo("RELIANCE");
    }
}
